function h($s) { return htmlspecialchars((string)$s, ENT_QUOTES, 'UTF-8'); }
function img($k) { return '?img=' . $k; }
function url($p, $extra = '') { return '?page=' . $p . $extra; }
function tel($n) { return 'tel:' . preg_replace('/[^0-9+]/', '', $n); }

/* ---------------- FORM HANDLER ---------------- */
$flash = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['form'])) {
  if (!hash_equals($_SESSION['csrf'] ?? '', $_POST['csrf'] ?? '') || !empty($_POST['website'])) {
    $flash = 'error';
  } else {
    $f = [];
    foreach (['form','name','email','phone','state','city','message','plan'] as $key) {
      $f[$key] = trim(strip_tags($_POST[$key] ?? ''));
    }
    if ($f['name'] === '' || $f['phone'] === '' || ($f['email'] !== '' && !filter_var($f['email'], FILTER_VALIDATE_EMAIL))) {
      $flash = 'error';
    } else {
      $row = [date('Y-m-d H:i:s'), $f['form'], $f['name'], $f['email'], $f['phone'], $f['state'], $f['city'], $f['message'], $f['plan']];
      $fp = @fopen(__DIR__ . '/enquiries.csv', 'a');
      if ($fp) { fputcsv($fp, $row); fclose($fp); }
      $body = "New enquiry ({$f['form']})\n\n";
      foreach ($f as $k2 => $v) { if ($v !== '') $body .= ucfirst($k2) . ": $v\n"; }
      @mail($SITE['mail_to'], 'Website Enquiry – ' . $f['name'], $body, 'From: noreply@' . ($_SERVER['HTTP_HOST'] ?? 'localhost'));
      $flash = 'ok';
    }
  }
  $_SESSION['flash'] = $flash;
  $back = $_POST['back'] ?? 'home';
  header('Location: ?page=' . preg_replace('/[^a-z\-]/', '', $back) . '#' . ($_POST['form'] === 'plan' ? 'planner' : 'contact'));
  exit;
}
if (!empty($_SESSION['flash'])) { $flash = $_SESSION['flash']; unset($_SESSION['flash']); }
if (empty($_SESSION['csrf'])) $_SESSION['csrf'] = bin2hex(random_bytes(16));
function csrf($back, $form) {
  return '<input type="hidden" name="csrf" value="' . $_SESSION['csrf'] . '"><input type="hidden" name="back" value="' . h($back) . '"><input type="hidden" name="form" value="' . h($form) . '"><input type="text" name="website" class="hp" tabindex="-1" autocomplete="off">';
}

