/* ---------------- REUSABLE UI PIECES ---------------- */
function eyebrow($t, $line = true) { return '<div class="eyebrow">' . ($line ? '<span></span>' : '') . h($t) . '</div>'; }
function script($t, $cls = '') { return '<div class="script ' . $cls . '">' . $t . '<i></i></div>'; }
function vtag($lines) { return '<div class="vtag">' . implode('<br>', array_map('h', $lines)) . '<i></i></div>'; }
function arrows() { return '<div class="arrows"><button class="circ" data-dir="-1" aria-label="Previous">' . ic('larrow', 18) . '</button><button class="circ" data-dir="1" aria-label="Next">' . ic('arrow', 18) . '</button></div>'; }
function cta_bar($title, $sub, $eyebrow = "LET'S BUILD TOGETHER", $dark = false, $side = []) {
  $o = '<div class="ctabar' . ($dark ? ' dark' : '') . '"><div class="ctabar-main"><div class="ctabar-ic">' . ic('home', 38) . '</div><div><div class="mini">' . h($eyebrow) . '</div><h3>' . h($title) . '</h3><p>' . h($sub) . '</p></div><a class="btn" href="' . url('contact') . '">Book Free Consultation ' . ic('arrow', 16) . '</a></div>';
  if ($side) {
    $o .= '<div class="ctabar-side">';
    foreach ($side as $s) $o .= '<div>' . ic($s[0], 26) . '<span>' . $s[1] . '</span></div>';
    $o .= '</div>';
  }
  return $o . '</div>';
}
function page_hero($eyebrowT, $title, $sub, $imgk, $scriptT = 'Better Spaces<br>Brighter Lives') {
  return '<section class="phero" style="--bg:url(\'' . img($imgk) . '\')"><div class="wrap"><div class="phero-in">' . eyebrow($eyebrowT, false) . '<h1>' . $title . '</h1><p>' . h($sub) . '</p>' . script($scriptT, 'dk') . '</div><div class="phero-side">ARCHITECTURE<br>CONSTRUCTION<br>INTERIOR<i></i></div></div></section>'
   . '<div class="crumbs wrap"><a href="' . url('home') . '">Home</a> ' . ic('chev', 12) . ' <span>' . strip_tags($title) . '</span></div>';
}

