function site_css() { ?>
:root{--gold:#a87c4a;--gold2:#c49a66;--goldl:#e9d9c3;--ink:#14171c;--ink2:#1c2027;--txt:#4b5058;--mut:#7b8089;--cream:#f7f3ee;--cream2:#efe7dc;--line:#e6ded3;--white:#fff;--serif:'Playfair Display',Georgia,serif;--sans:'Inter',system-ui,sans-serif;--script:'Mrs Saint Delafield',cursive;--r:8px;--sh:0 10px 30px rgba(40,30,20,.08)}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{font-family:var(--sans);color:var(--txt);background:#fbf9f6;line-height:1.6;font-size:15px;-webkit-font-smoothing:antialiased}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
button,input,select,textarea{font:inherit}
.wrap{width:min(1240px,92%);margin:auto}
.hp{position:absolute;left:-9999px}
h1,h2,h3,h4{font-family:var(--serif);color:var(--ink);line-height:1.12;font-weight:700}
h2{font-size:clamp(30px,3.6vw,46px);letter-spacing:-.3px}
.ic{flex:none}
.sec{padding:80px 0;position:relative;overflow:hidden}
.sec.cream{background:var(--cream)}
.eyebrow{display:flex;align-items:center;gap:14px;font-size:11.5px;letter-spacing:2.2px;color:var(--gold);font-weight:600;text-transform:uppercase;margin-bottom:14px}
.eyebrow span{width:40px;height:1px;background:var(--gold)}
.center .eyebrow{justify-content:center}
.lead{color:var(--mut);max-width:560px;margin-top:14px;font-size:15.5px}
.center{text-align:center}.center .lead{margin-inline:auto}
.script{font-family:var(--script);font-size:40px;line-height:.95;color:var(--ink);transform:rotate(-12deg);display:inline-block;position:relative}
.script i{display:block;width:70%;height:2px;background:var(--gold);margin:8px 0 0 20%;transform:rotate(-4deg)}
.script.dk{color:var(--ink)}.script.lt{color:#fff}
.vtag{font-size:11px;letter-spacing:2.6px;color:var(--ink);line-height:1.9;border-left:1px solid var(--ink);padding-left:14px;text-transform:uppercase}
.vtag i{display:block;width:30px;height:2px;background:var(--gold);margin-top:8px}
.shead{display:flex;justify-content:space-between;align-items:flex-end;gap:30px;margin-bottom:40px;flex-wrap:wrap}
.shead-r{display:flex;align-items:center;gap:40px}
.btn{display:inline-flex;align-items:center;gap:10px;background:var(--gold);color:#fff;padding:12px 24px;border-radius:5px;font-weight:500;font-size:14.5px;border:0;cursor:pointer;transition:.25s;white-space:nowrap}
.btn:hover{background:#8f6639;transform:translateY(-2px)}
.btn.dark{background:var(--ink)}.btn.dark:hover{background:#000}
.btn.ghost{background:transparent;color:var(--gold);border:1px solid var(--gold)}.btn.ghost:hover{background:var(--gold);color:#fff}
.btn.green{background:#25a244}.btn.green:hover{background:#1c8636}
.link{display:inline-flex;align-items:center;gap:8px;font-weight:600;font-size:13.5px;color:var(--ink);padding-bottom:4px;border-bottom:1.5px solid var(--gold);transition:.2s}
.link:hover{gap:12px;color:var(--gold)}
.link.gold{color:var(--gold);border:0}
.circ{width:44px;height:44px;border-radius:50%;border:1px solid #cfc6ba;background:#fff;display:grid;place-items:center;cursor:pointer;color:var(--ink);transition:.2s}
.circ:hover{background:var(--gold);color:#fff;border-color:var(--gold)}
.arrows{display:flex;gap:12px}
.card{background:#fff;border-radius:var(--r);box-shadow:var(--sh);overflow:hidden}
.zoom{overflow:hidden;display:block}.zoom img{transition:transform .6s}.card:hover .zoom img,.zoom:hover img{transform:scale(1.06)}
.reveal{opacity:0;transform:translateY(30px);transition:1s cubic-bezier(.2,.7,.2,1)}
.reveal.in{opacity:1;transform:none}
.slider{display:flex;gap:24px;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;scroll-behavior:smooth}
.slider::-webkit-scrollbar{display:none}
.slider>*{scroll-snap-align:start}
.dots{display:flex;justify-content:center;gap:8px;margin-top:22px}
.dots b{width:9px;height:9px;border-radius:50%;background:#ddd6cc}.dots b:first-child{background:var(--gold)}

/* topbar + header */
.topbar{background:var(--ink);color:#e6e6e6;font-size:13px}
.topbar .wrap{display:flex;justify-content:space-between;align-items:center;height:38px}
.tb-l{display:flex;align-items:center;gap:9px}
.sc{width:21px;height:21px;border-radius:50%;display:grid;place-items:center;color:#fff}
.sc.fb{background:#1877f2}.sc.ig{background:radial-gradient(circle at 30% 110%,#fdc468,#df4996 50%,#7a3ce0)}.sc.yt{background:#ff0000}.sc.pt{background:#e60023}
.tb-r{display:flex;gap:26px}.tb-r span,.tb-r a{display:flex;align-items:center;gap:7px}
.hdr{background:#fff;position:sticky;top:0;z-index:50;border-bottom:1px solid #eee;transition:.3s}
.hdr.sticky{box-shadow:0 6px 20px rgba(0,0,0,.07)}
.hdr .wrap{display:flex;align-items:center;justify-content:space-between;height:78px;gap:20px}
.brand{display:flex;align-items:center;gap:10px}
.brand img{height:50px;width:auto}
.brand{flex:none}.brand b{white-space:nowrap;display:block;font-family:var(--serif);font-size:21px;color:#1b3a8a;letter-spacing:.5px;line-height:1.1}
.brand small{white-space:nowrap;font-size:10.5px;color:var(--txt);letter-spacing:.3px}
.nav{display:flex;align-items:center;gap:32px}
.nav>a,.dd>a{font-size:14.5px;color:var(--ink);font-weight:500;position:relative;padding:28px 0;display:flex;align-items:center;gap:4px}
.nav>a::after{content:'';position:absolute;left:0;right:0;bottom:20px;height:2px;background:var(--gold);transform:scaleX(0);transition:.25s}
.nav>a:hover::after,.nav>a.on::after{transform:scaleX(1)}
.nav-cta{display:none!important}
.dd{position:relative}
.dd-menu{position:absolute;top:100%;left:-20px;background:#fff;min-width:250px;border-radius:8px;box-shadow:0 20px 40px rgba(0,0,0,.12);padding:10px;opacity:0;visibility:hidden;transform:translateY(10px);transition:.25s;border-top:2px solid var(--gold)}
.dd:hover .dd-menu{opacity:1;visibility:visible;transform:none}
.dd-menu a{display:flex;gap:10px;align-items:center;padding:10px 12px;border-radius:6px;font-size:14px;color:var(--ink)}
.dd-menu a:hover{background:var(--cream);color:var(--gold)}
.hdr-r{display:flex;align-items:center;gap:26px}
.hdr-ph{white-space:nowrap;display:flex;align-items:center;gap:9px;font-weight:600;color:var(--ink);font-size:15px}
.burger{display:none;background:none;border:0;color:var(--ink);cursor:pointer}

/* HERO */
.hero{position:relative;min-height:640px;display:flex;align-items:center;color:#fff;overflow:hidden;background:#0d0f12}
.hero-bg{position:absolute;inset:0;background:url('<?= img('dark') ?>') center/cover;transform:scale(1.05);animation:kb 18s ease-in-out infinite alternate}
@keyframes kb{to{transform:scale(1.15) translateX(-2%)}}
.hero::before{content:'';position:absolute;inset:0;background:linear-gradient(90deg,rgba(8,9,11,.92) 0%,rgba(8,9,11,.7) 42%,rgba(8,9,11,.15) 75%),linear-gradient(0deg,rgba(8,9,11,.6),transparent 40%);z-index:1}
.hero .wrap{position:relative;z-index:2;padding:80px 0}
.hero .eyebrow{color:var(--gold2)}.hero .eyebrow span{background:var(--gold2)}
.hero h1{color:#fff;font-size:clamp(40px,5.6vw,74px);line-height:1.05;max-width:720px}
.hero h1 em{font-style:normal;color:var(--gold2)}
.hero p{max-width:560px;margin:20px 0 30px;color:#d6d6d6;font-size:17px}
.hero-feat{display:flex;gap:28px;margin-bottom:36px;flex-wrap:wrap}
.hero-feat div{display:flex;gap:12px;align-items:center;padding-right:28px;border-right:1px solid rgba(255,255,255,.25)}
.hero-feat div:last-child{border:0}
.hero-feat svg{color:var(--gold2)}
.hero-feat b{display:block;font-weight:500;font-size:15px}.hero-feat small{font-size:10.5px;letter-spacing:1.2px;color:#bbb;text-transform:uppercase}
.hero-btns{display:flex;gap:16px;flex-wrap:wrap}
.bigbtn{display:flex;align-items:center;gap:16px;padding:14px 22px;border-radius:6px;background:var(--gold);color:#fff;min-width:250px;transition:.25s}
.bigbtn:hover{transform:translateY(-3px);box-shadow:0 10px 30px rgba(0,0,0,.3)}
.bigbtn.green{background:#1f9d44}
.bigbtn b{display:block;font-size:16px;font-weight:600}.bigbtn small{font-size:12.5px;opacity:.9}
.bigbtn .ic:last-child{margin-left:auto}
.hero .script{position:absolute;right:4%;top:22%;color:#fff;font-size:54px;z-index:2}
.hero-trust{position:absolute;right:4%;bottom:34px;z-index:2;display:flex;background:rgba(10,12,15,.72);backdrop-filter:blur(6px);border:1px solid rgba(255,255,255,.15);border-radius:8px;padding:14px 8px}
.hero-trust div{display:flex;gap:10px;align-items:center;font-size:12px;padding:0 18px;border-right:1px solid rgba(255,255,255,.2);line-height:1.35}
.hero-trust div:last-child{border:0}

/* services */
.svc-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}
.svc .zoom{height:190px}.svc .zoom img{width:100%;height:100%;object-fit:cover}
.svc-body{padding:0 22px 24px;position:relative}
.svc-ic{width:54px;height:54px;border-radius:50%;background:#f6eee3;border:3px solid #fff;display:grid;place-items:center;color:var(--gold);margin-top:-27px;position:relative;box-shadow:0 4px 10px rgba(0,0,0,.08)}
.svc h3{font-size:19px;margin:14px 0 8px}
.svc p{font-size:13.5px;color:var(--mut);margin-bottom:16px;min-height:62px}
.ctabar{display:flex;gap:16px;margin-top:40px;align-items:stretch}
.ctabar-main{flex:1;display:flex;align-items:center;gap:26px;background:linear-gradient(90deg,#f1e8dc,#f7f1e9);border-radius:var(--r);padding:26px 34px;flex-wrap:wrap}
.ctabar-main>div:nth-child(2){flex:1;min-width:240px}
.ctabar .mini{font-size:10.5px;letter-spacing:2px;color:var(--gold);font-weight:600}
.ctabar h3{font-size:28px;margin:4px 0}
.ctabar p{font-size:14px}
.ctabar-ic{color:var(--ink)}
.ctabar.dark .ctabar-main{background:linear-gradient(90deg,#15181d,#262a31);color:#ccc}
.ctabar.dark h3,.ctabar.dark .ctabar-ic{color:#fff}
.ctabar-side{display:flex;background:#efe9e1;border-radius:var(--r);align-items:center;padding:14px 10px}
.ctabar-side div{display:flex;flex-direction:column;align-items:center;gap:8px;padding:6px 22px;text-align:center;font-size:12.5px;color:var(--ink);border-right:1px solid #d6cbbc}
.ctabar-side div:last-child{border:0}
.ctabar-side svg{color:var(--ink)}

/* signature projects */
.sig-grid{display:grid;grid-template-columns:1.6fr 1fr 1fr;grid-template-rows:260px 260px;gap:14px}
.sig{position:relative;border-radius:var(--r);overflow:hidden;color:#fff;display:block}
.sig img{width:100%;height:100%;object-fit:cover;transition:transform .7s}
.sig:hover img{transform:scale(1.07)}
.sig::after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,rgba(0,0,0,.82),rgba(0,0,0,0) 55%)}
.sig.big{grid-row:span 2}
.sig .num{position:absolute;top:16px;right:18px;z-index:2;font-size:14px;opacity:.85}
.sig .tag{position:absolute;top:18px;left:18px;z-index:2;background:rgba(0,0,0,.7);font-size:10.5px;letter-spacing:1.4px;padding:6px 12px;border-radius:3px}
.sig-info{position:absolute;left:20px;right:20px;bottom:18px;z-index:2}
.sig-info h3{color:#fff;font-size:22px;margin-bottom:8px}
.sig.big h3{font-size:34px}
.meta{display:flex;gap:18px;font-size:12px;flex-wrap:wrap;opacity:.9}
.meta span{display:flex;align-items:center;gap:6px}
.sig.big p{font-size:14px;margin:14px 0 18px;max-width:320px;opacity:.9}
.bandline{display:flex;justify-content:space-between;align-items:center;font-size:10.5px;letter-spacing:2.5px;color:var(--mut);margin-top:34px;gap:20px}
.bandline span{display:flex;gap:18px;align-items:center}
.bandline span::before{content:'';width:40px;height:1px;background:#bbb}

/* elevations */
.tabs{display:flex;gap:10px;flex-wrap:wrap;margin:26px 0}
.tab{padding:9px 24px;border:1px solid #e1dbd2;background:#fff;border-radius:4px;font-size:13.5px;color:var(--ink);cursor:pointer;display:flex;align-items:center;gap:10px;transition:.2s}
.tab:hover{border-color:var(--gold)}
.tab.on{background:var(--gold);color:#fff;border-color:var(--gold)}
.el-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.el{position:relative;border-radius:6px;overflow:hidden;aspect-ratio:1.55;cursor:zoom-in}
.el img{width:100%;height:100%;object-fit:cover;transition:.6s}
.el:hover img{transform:scale(1.07)}
.el-bar{white-space:nowrap;position:absolute;left:0;right:0;bottom:0;background:linear-gradient(0deg,rgba(0,0,0,.9),rgba(0,0,0,.35));color:#fff;display:flex;justify-content:space-between;padding:8px 10px;font-size:10.5px;gap:4px}
.el-bar span{display:flex;align-items:center;gap:5px}.el-bar b{font-weight:600}
.el-more{border-radius:6px;background:linear-gradient(rgba(245,243,240,.9),rgba(245,243,240,.9)),url('<?= img('el7') ?>') center/cover;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:20px}
.el-more .circ{margin-bottom:12px;background:transparent;border-color:var(--ink)}
.el-more h4{font-size:18px}.el-more p{font-size:12.5px;color:var(--mut);margin:6px 0 14px;max-width:180px}
.featstrip{display:flex;align-items:center;justify-content:space-between;background:#f3eee7;padding:20px 30px;margin-top:40px;border-radius:var(--r);gap:20px;flex-wrap:wrap}
.featstrip>div{display:flex;gap:12px;align-items:center;padding-right:18px;border-right:1px solid #d9cfc2}
.featstrip>div:nth-last-child(2){border:0}
.featstrip b{display:block;font-family:var(--serif);color:var(--ink);font-size:14.5px}
.featstrip small{font-size:12px}
.featstrip svg{color:var(--ink)}

/* interiors */
.int-grid{display:grid;grid-template-columns:1.8fr 1fr 1fr 1fr;grid-template-rows:auto auto;gap:10px}
.int{position:relative;border-radius:6px;overflow:hidden;min-height:180px;cursor:zoom-in;color:#fff}
.int img{width:100%;height:100%;object-fit:cover;position:absolute;inset:0;transition:.6s}
.int:hover img{transform:scale(1.07)}
.int::after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,rgba(0,0,0,.75),transparent 55%)}
.int.big{grid-row:span 2;min-height:380px}
.int .zm{position:absolute;top:10px;right:10px;width:30px;height:30px;border-radius:50%;background:rgba(20,20,20,.75);display:grid;place-items:center;z-index:2}
.int-info{position:absolute;left:14px;bottom:10px;z-index:2}
.int-info h4{color:#fff;font-size:15px}.int-info small{font-size:11.5px}
.int.big h4{font-size:30px}.int.big small{font-size:14px;display:block;margin:4px 0 12px}
.int .cnt{position:absolute;right:16px;bottom:14px;z-index:2;font-size:13px}

/* process */
.proc{position:relative;margin-top:50px}
.proc::before{content:'';position:absolute;left:50%;top:0;bottom:0;border-left:1.5px dashed #cdb89d}
.pstep{display:flex;width:50%;margin-bottom:-40px;position:relative;align-items:stretch}
.pstep:nth-child(odd){padding-right:40px}
.pstep:nth-child(even){margin-left:50%;padding-left:40px;flex-direction:row-reverse}
.pstep::after{content:'';position:absolute;top:50%;width:12px;height:12px;border-radius:50%;background:var(--gold);box-shadow:0 0 0 5px #f3eadf}
.pstep:nth-child(odd)::after{right:-6px}.pstep:nth-child(even)::after{left:-6px}
.pstep img{width:42%;object-fit:cover;border-radius:6px 0 0 6px}
.pstep:nth-child(even) img{border-radius:0 6px 6px 0}
.pbody{flex:1;background:#fff;padding:26px 24px;box-shadow:var(--sh);border-radius:0 6px 6px 0;display:grid;grid-template-columns:48px 1fr;gap:4px 16px;position:relative}
.pstep:nth-child(even) .pbody{border-radius:6px 0 0 6px}
.pnum{position:absolute;top:-16px;left:-16px;width:44px;height:44px;border-radius:50%;background:#f1e4d3;color:var(--ink);display:grid;place-items:center;font-weight:600;font-size:15px}
.pbody>svg{grid-row:span 3;color:var(--ink);margin-top:4px}
.pbody h3{font-size:21px}
.pbody p{font-size:13.5px;color:var(--mut)}
.pbody .link{justify-self:start;margin-top:8px;font-size:12.5px}
.pstep:last-child{margin-bottom:0}
.proc-note{position:absolute;font-family:var(--script);font-size:30px;color:var(--ink);transform:rotate(-10deg);line-height:1}
.bigcta{display:flex;align-items:center;gap:26px;background:linear-gradient(90deg,#15181d,#2a2e35);border-radius:var(--r);padding:26px 34px;color:#ccc;margin-top:60px;flex-wrap:wrap}
.bigcta h3{color:#fff;font-size:28px}.bigcta .mini{font-size:10.5px;letter-spacing:2px;color:#bbb}
.bigcta>div:nth-child(2){flex:1;min-width:260px}
.bigcta .ctabar-ic{color:#fff}
.bigcta .cc{display:flex;gap:12px;align-items:center;padding-left:24px;border-left:1px solid #444;color:#fff}
.bigcta .cc small{display:block;color:#bbb;font-size:12px}.bigcta .cc b{font-weight:600}

/* planner */
.plan-top{display:flex;gap:30px;align-items:center}
.plan-top div{text-align:center;font-size:12px;color:var(--mut)}
.plan-top div b{display:block;color:var(--ink);font-size:13px;font-weight:600}
.plan-top .ico{display:grid!important;width:50px;height:50px;margin:0 auto 8px;border-radius:50%;border:1.5px solid var(--gold);display:grid;place-items:center;color:var(--gold)}
.plan-grid{display:grid;grid-template-columns:1fr 1.15fr;gap:20px}
.pform{padding:26px}
.pform h4,.preview h4{font-size:19px;display:flex;align-items:center;gap:12px;margin-bottom:16px}
.pform h4 i{font-style:normal;width:28px;height:28px;border-radius:50%;background:#f1e4d3;font-family:var(--sans);font-size:14px;display:grid;place-items:center}
.pform h4 small{font-family:var(--sans);font-weight:400;font-size:13px;color:var(--mut)}
.fg{display:grid;grid-template-columns:1fr 1fr;gap:14px 20px;margin-bottom:22px}
.fg.full{grid-template-columns:1fr}
.field label{display:block;font-size:13px;color:var(--ink);margin-bottom:6px;font-weight:500}
.field label em{color:#c0392b;font-style:normal}
.inp{display:flex;align-items:center;border:1px solid #e1dbd2;border-radius:5px;background:#fff;transition:.2s}
.inp:focus-within{border-color:var(--gold);box-shadow:0 0 0 3px rgba(168,124,74,.12)}
.inp>svg{margin:0 10px 0 12px;color:#777}
.inp.sep>svg{margin:0;padding:0 10px;width:40px;border-right:1px solid #e1dbd2;height:22px}
.inp input,.inp select,.inp textarea{flex:1;border:0;outline:0;background:transparent;padding:11px 12px 11px 4px;font-size:13.5px;color:var(--ink);min-width:0}
.inp.sep input,.inp.sep select{padding-left:12px}
.inp textarea{min-height:90px;resize:vertical;padding-top:12px}
.inp.ta{align-items:flex-start}.inp.ta>svg{margin-top:13px}
hr.soft{border:0;border-top:1px solid #eee;margin:4px 0 22px}
.checks{display:grid;grid-template-columns:repeat(4,1fr);gap:12px 10px;font-size:13px;margin-bottom:22px}
.checks label{display:flex;align-items:center;gap:8px;cursor:pointer}
.checks input{accent-color:var(--gold);width:17px;height:17px}
.btn.block{width:100%;justify-content:center;padding:13px}
.preview{background:linear-gradient(90deg,#fff 50%,rgba(255,255,255,.3)),url('<?= img('why') ?>') right/cover;padding:22px;position:relative;min-height:600px}
.preview>p{font-size:13px;color:var(--mut);margin:-10px 0 14px}
.pv-in{display:grid;grid-template-columns:1.2fr 1fr;gap:16px}
.pv-tabs{display:flex;gap:6px;margin-bottom:10px}
.pv-tabs .tab{padding:7px 14px;font-size:12.5px}
.pv-img{border-radius:6px;overflow:hidden;border:6px solid #fff;box-shadow:var(--sh);height:360px}
.pv-img img{width:100%;height:100%;object-fit:cover;transition:.4s}
.summary{background:#fff;border-radius:6px;box-shadow:var(--sh);padding:18px}
.summary h5{font-family:var(--serif);font-size:17px;color:var(--ink);display:flex;justify-content:space-between;margin-bottom:12px}
.summary dl{display:grid;grid-template-columns:1fr 1.2fr;font-size:12px;gap:9px 8px;border-top:1px solid #eee;padding-top:12px;margin-bottom:16px}
.summary dt{color:var(--mut)}.summary dd{color:var(--ink)}
.summary .btn{margin-bottom:10px}
.safe{display:flex;gap:6px;align-items:center;justify-content:center;font-size:12px;color:var(--mut)}
.getplan{position:absolute;left:10%;bottom:-30px;width:300px;background:#fff;border-radius:8px;box-shadow:0 20px 50px rgba(0,0,0,.2);padding:20px;z-index:3}
.getplan h5{font-family:var(--serif);font-size:17px;color:var(--ink)}
.getplan>p{font-size:12px;color:var(--mut);margin-bottom:12px}
.getplan .field{margin-bottom:10px}
.getplan .inp input{padding:8px 6px}
.getplan .x{position:absolute;right:14px;top:14px;background:none;border:0;cursor:pointer}
.getplan small{display:block;text-align:center;font-size:10.5px;color:var(--mut);margin-top:10px}
.plan-feats{display:flex;gap:0;background:#f3eee7;padding:18px 20px;border-radius:var(--r);margin-top:20px;width:48%}
.plan-feats div{display:flex;gap:12px;align-items:center;font-size:13px;color:var(--ink);padding:0 18px;border-right:1px solid #d9cfc2;font-weight:500}
.plan-feats div:last-child{border:0}.plan-feats svg{color:var(--gold)}

/* why */
.why{background:linear-gradient(90deg,#f5f0e9 55%,rgba(245,240,233,.2) 75%),url('<?= img('why') ?>') right/auto 100% no-repeat,#f5f0e9;padding-bottom:0}
.why-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;max-width:780px;margin-top:30px}
.why-card{background:rgba(250,246,240,.95);border:1px solid #ebe1d4;border-radius:var(--r);padding:26px 18px;text-align:center;transition:.3s}
.why-card:hover{transform:translateY(-6px);box-shadow:var(--sh);background:#fff}
.why-card .ico{width:56px;height:56px;border-radius:50%;border:1.5px solid var(--ink);display:grid;place-items:center;margin:0 auto 14px;color:var(--ink)}
.why-card h3{font-size:17px;margin-bottom:8px}
.why-card p{font-size:12.5px;margin-bottom:14px}
.why-card .link{border-color:var(--gold);font-size:12.5px}
.statsbar{background:#ece4d9;margin-top:40px;padding:22px 0}
.statsbar .wrap{display:flex;align-items:center;gap:0;flex-wrap:wrap}
.statsbar .wrap>div{display:flex;gap:14px;align-items:center;padding:0 30px;border-right:1px solid #cfc3b3}
.statsbar .wrap>div:first-child{padding-left:0}
.statsbar b{font-family:var(--serif);color:var(--ink);display:block}.statsbar small{font-size:12px}
.statsbar .wrap>span{margin-left:auto;font-size:11px;letter-spacing:2.5px;display:flex;align-items:center;gap:18px}
.statsbar .wrap>span::before{content:'';width:70px;height:1px;background:#999}

/* visualizer */
.viz-feats{display:flex;gap:26px;text-align:center;font-size:12px;color:var(--ink)}
.viz-feats .ico{width:50px;height:50px;border-radius:50%;border:1.5px solid var(--gold);display:grid;place-items:center;margin:0 auto 8px;color:var(--gold)}
.viz-grid{display:grid;grid-template-columns:230px 1fr;gap:18px}
.viz-menu{display:flex;flex-direction:column;gap:6px}
.viz-menu button{display:flex;align-items:center;gap:14px;padding:16px;background:#fff;border:1px solid #eee;border-radius:4px;font-size:14px;color:var(--ink);cursor:pointer;text-align:left;transition:.2s}
.viz-menu button .ic:last-child{margin-left:auto}
.viz-menu button.on,.viz-menu button:hover{background:var(--gold);color:#fff;border-color:var(--gold)}
.help{background:#f3eee7;border-radius:6px;padding:20px;margin-top:10px}
.help div{display:flex;gap:12px;margin-bottom:16px;font-size:12.5px}
.help b{display:block;font-family:var(--serif);color:var(--ink);font-size:15px}
.help svg{color:var(--gold)}
.viz-main{position:relative;border-radius:6px;overflow:hidden;height:380px}
.viz-main img{width:100%;height:100%;object-fit:cover;transition:filter .6s}
.viz-label{position:absolute;left:14px;top:14px;background:rgba(20,22,26,.85);color:#fff;padding:12px 16px;border-radius:6px;max-width:230px}
.viz-label b{font-family:var(--serif);font-size:16px;display:block}.viz-label small{font-size:12px;color:#ccc}
.viz-label i{display:block;width:30px;height:2px;background:var(--gold);margin-top:6px}
.viz-reset{position:absolute;right:14px;bottom:14px;background:rgba(20,22,26,.85);color:#fff;border:0;border-radius:4px;padding:7px 12px;font-size:12px;display:flex;gap:6px;align-items:center;cursor:pointer}
.themes{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:10px}
.theme{background:#fff;border:1.5px solid #eee;border-radius:5px;overflow:hidden;cursor:pointer;position:relative;text-align:left;padding:0;transition:.2s}
.theme.on{border-color:var(--gold)}
.theme img{height:70px;width:100%;object-fit:cover}
.theme b{display:block;font-family:var(--serif);font-size:13.5px;color:var(--ink);padding:8px 10px 4px}
.theme .sw{display:flex;gap:6px;padding:0 10px 10px}
.theme .sw i{width:20px;height:20px;border-radius:50%}
.theme .tick{position:absolute;top:6px;right:6px;width:22px;height:22px;border-radius:50%;background:var(--gold);color:#fff;display:none;place-items:center}
.theme.on .tick{display:grid}
.mats{display:flex;align-items:center;gap:22px;background:#f3eee7;padding:18px 26px;border-radius:var(--r);margin-top:26px;flex-wrap:wrap}
.mats>div:first-child{min-width:190px;padding-right:20px;border-right:1px solid #d9cfc2}
.mats h4{font-size:19px}.mats>div:first-child small{font-size:12px}
.mat-list{display:flex;gap:10px;flex:1;flex-wrap:wrap}
.mat{text-align:center;font-size:11px;color:var(--ink)}
.mat img{width:64px;height:46px;object-fit:cover;border-radius:2px;margin-bottom:5px;transition:.2s}
.mat:hover img{transform:scale(1.1)}

/* recent projects */
.rp{min-width:calc(25% - 18px)}
.rp .zoom{height:190px;position:relative}.rp .zoom img{width:100%;height:100%;object-fit:cover}
.badge{position:absolute;top:14px;left:14px;padding:5px 12px;border-radius:30px;font-size:10.5px;letter-spacing:.5px;color:#fff;background:var(--gold);display:flex;gap:6px;align-items:center;z-index:2}
.badge.dk{background:var(--ink)}
.rp-body{padding:16px 16px 18px}
.rp-loc{display:flex;justify-content:space-between;font-size:11.5px;color:var(--ink)}
.rp-loc span{display:flex;align-items:center;gap:5px}
.rp h3{font-size:19px;margin:12px 0 6px}
.rp p{font-size:12.5px;color:var(--mut);min-height:38px}
.specs{display:flex;border-top:1px solid #eee;border-bottom:1px solid #eee;margin:14px 0;padding:10px 0}
.specs div{flex:1;display:flex;gap:8px;align-items:center;font-size:12px;border-right:1px solid #eee;padding-left:8px;line-height:1.25}
.specs div:first-child{padding-left:0}.specs div:last-child{border:0}
.specs small{display:block;color:var(--mut);font-size:11px}
.rp-foot{display:flex;justify-content:space-between;align-items:center}
.rp-foot .link{border-color:var(--gold);font-size:12.5px}
.go{width:34px;height:34px;border-radius:50%;background:#f3e8db;color:var(--ink);display:grid;place-items:center;transition:.2s}
.go:hover{background:var(--gold);color:#fff}
.story{background:linear-gradient(90deg,rgba(16,17,20,.92) 40%,rgba(16,17,20,.65)),url('<?= img('stairs') ?>') center/cover;color:#ddd;padding:34px 0}
.story .wrap{display:flex;align-items:center;justify-content:space-between;gap:30px;flex-wrap:wrap}
.story .mini{font-size:10.5px;letter-spacing:2px;color:var(--gold2)}
.story h3{color:#fff;font-size:32px;margin:6px 0}
.story .btn{margin-top:16px}
.story-stats{display:flex}
.story-stats div{text-align:center;padding:0 28px;border-left:1px solid rgba(255,255,255,.3);color:#fff;font-size:13px}
.story-stats svg{display:block;color:#fff;margin:0 auto 6px}
.story-stats b{display:block;font-size:22px;font-weight:600}

/* achievements */
.ach{background:linear-gradient(90deg,#0d1016 32%,rgba(13,16,22,.2) 65%,rgba(13,16,22,.35)),linear-gradient(0deg,#0d1016 38%,rgba(13,16,22,0) 75%),url('<?= img('dark') ?>') right top/65% auto no-repeat,#0d1016;color:#bbb;padding:70px 0 60px}
.ach h2{color:#fff;margin-bottom:18px}
.ach .eyebrow{color:var(--gold2)}
.ach p.lead{color:#c8c8c8}
.ach-grid{display:grid;grid-template-columns:repeat(4,1fr);margin-top:60px}
.ach-grid div{text-align:center;padding:0 20px;border-right:1px solid rgba(255,255,255,.12)}
.ach-grid div:last-child{border:0}
.ach-grid .ico{width:54px;height:54px;border-radius:50%;border:1.5px solid var(--gold2);color:var(--gold2);display:grid;place-items:center;margin:0 auto 10px}
.ach-grid b{font-family:var(--serif);font-size:48px;color:var(--goldl);display:block;line-height:1.2}
.ach-grid h4{font-family:var(--sans);font-weight:500;color:#fff;letter-spacing:2.5px;font-size:15px;margin:4px 0 12px}
.ach-grid p{font-size:13px;color:#aaa}
.ach-grid i{display:block;width:30px;height:2px;background:var(--gold);margin:16px auto 0}
.ach .vtag{position:absolute;right:4%;top:34%;color:#ddd;border-color:transparent}

/* faq */
.faq-wrap{display:grid;grid-template-columns:1fr 32%;min-height:640px}
.faq-l{padding:70px 4% 60px 8%;position:relative}
.acc{margin-top:30px}
.qa{border:1px solid #e8e2d9;border-radius:6px;margin-bottom:10px;background:#f7f5f1;transition:.3s}
.qa.open{background:#f4ede3;border-color:#c9a57b}
.qa button{width:100%;display:flex;align-items:center;gap:16px;padding:14px 16px;background:none;border:0;cursor:pointer;text-align:left;font-family:var(--serif);font-size:16.5px;font-weight:600;color:var(--ink)}
.qa button i{font-style:normal;width:30px;height:30px;border-radius:50%;background:#ece4d9;font-family:var(--sans);font-size:12px;display:grid;place-items:center;flex:none}
.qa.open button i{background:var(--gold);color:#fff}
.qa button>span{margin-left:auto;display:flex}
.qa .ans{max-height:0;overflow:hidden;transition:max-height .4s}
.qa .ans p{padding:0 22px 18px 62px;font-size:14px}
.qa .mn{display:none}.qa.open .mn{display:block}.qa.open .pl{display:none}
.still{display:flex;align-items:center;gap:16px;border-top:1px solid #ddd;margin-top:30px;padding-top:22px;flex-wrap:wrap}
.still>div{flex:1}.still b{font-family:var(--serif);font-size:18px;color:var(--ink);display:block}
.still svg{color:var(--gold)}
.faq-r{background:#f5f1ec;display:flex;flex-direction:column}
.faq-img{flex:1;background:url('<?= img('stairs') ?>') center/cover;position:relative;min-height:360px}
.faq-img blockquote{position:absolute;right:10%;top:16%;color:#fff;font-family:var(--serif);font-size:22px;line-height:1.3;max-width:170px;text-shadow:0 2px 12px rgba(0,0,0,.6)}
.faq-img blockquote svg{color:var(--gold2);display:block;margin-bottom:8px}
.faq-img blockquote i{display:block;width:40px;height:2px;background:var(--gold);margin-top:14px}
.assist{background:#fff;margin:18px;border-radius:6px;padding:20px;box-shadow:var(--sh)}
.assist>div{display:flex;gap:14px;font-size:12.5px}
.assist b{font-family:var(--serif);font-size:16px;color:var(--ink);display:block}
.assist svg{color:var(--gold)}
.assist nav{display:flex;border-top:1px solid #eee;margin-top:14px;padding-top:12px}
.assist nav a{flex:1;display:flex;gap:8px;align-items:center;justify-content:center;font-size:13.5px;color:var(--ink);font-weight:500}
.assist nav a+a{border-left:1px solid #ddd}

/* testimonials */
.tst-sec{background:linear-gradient(90deg,#e8e2da,#f7f4f0 12%,#f7f4f0 88%,#e8e2da)}
.tst-row{display:flex;align-items:center;gap:16px}
.tst-row .slider{flex:1}
.tst{min-width:calc(33.333% - 16px);padding:18px 18px 10px;position:relative}
.stars{color:#b27c3c;display:flex;gap:2px}
.tst .q{position:absolute;right:20px;top:14px;color:#e8d8c4}
.tst blockquote{font-size:13.5px;color:var(--ink);margin:10px 0 16px;min-height:110px}
.who{display:flex;gap:14px;align-items:center;margin-bottom:14px}
.who img{width:52px;height:52px;border-radius:50%;object-fit:cover}
.who b{font-family:var(--serif);color:var(--ink);font-size:14.5px}
.who small{display:block;font-size:11.5px}
.tst .zoom{height:100px;border-radius:4px;position:relative}
.tst .zoom img{width:100%;height:100%;object-fit:cover}
.tst .zoom span{position:absolute;left:8px;bottom:8px;background:rgba(0,0,0,.7);color:#fff;font-size:10.5px;padding:3px 8px;border-radius:3px}
.tst-stats{display:grid;grid-template-columns:repeat(4,1fr);margin-top:30px}
.tst-stats div{display:flex;gap:14px;align-items:center;justify-content:center;border-right:1px solid #d9cfc2}
.tst-stats div:last-child{border:0}
.tst-stats svg{color:var(--gold)}
.tst-stats b{font-family:var(--serif);font-size:22px;color:var(--ink);display:block;line-height:1}
.tst-stats small{font-size:12px}

/* team */
.team-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.tm .zoom{height:230px}.tm .zoom img{width:100%;height:100%;object-fit:cover;object-position:top}
.tm-body{padding:16px 16px 14px}
.tm h3{font-size:18px}
.tm .role{font-size:11px;letter-spacing:1.3px;color:var(--gold);text-transform:uppercase;margin:4px 0 8px;display:block}
.tm p{font-size:13px;min-height:58px;border-bottom:1px solid #eee;padding-bottom:12px}
.tm nav{display:flex;gap:10px;padding-top:12px}
.tm nav a{width:32px;height:32px;border-radius:50%;background:#f3eee7;color:var(--ink);display:grid;place-items:center;transition:.2s}
.tm nav a:hover{background:var(--gold);color:#fff}
.join{display:flex;align-items:center;gap:40px;margin-top:30px;padding:26px 0;flex-wrap:wrap;position:relative}
.join>div:first-child{padding-right:40px;border-right:1px solid #ccc}
.join h3{font-size:30px;margin-bottom:8px}.join p{font-size:13px;margin-bottom:16px}
.join-vals{display:flex;gap:34px}
.join-vals div{text-align:center;font-size:12.5px;color:var(--ink)}
.join-vals svg{display:block;color:var(--gold);margin:0 auto 8px}

/* blog */
.blog-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.bc .zoom{height:210px;position:relative}.bc .zoom img{width:100%;height:100%;object-fit:cover}
.bc .badge{border-radius:3px;text-transform:uppercase;letter-spacing:1px}
.bc-body{padding:18px 20px 22px}
.bc-meta{display:flex;justify-content:space-between;font-size:12px}
.bc-meta span{display:flex;gap:6px;align-items:center;color:var(--ink)}
.bc h3{font-size:20px;margin:12px 0 10px}
.bc h3 a:hover{color:var(--gold)}
.bc p{font-size:13.5px;margin-bottom:16px}
.divline{display:flex;align-items:center;gap:14px;font-size:10.5px;letter-spacing:2.5px;color:var(--mut);margin-top:40px}
.divline::before,.divline::after{content:'';flex:1;height:1px;background:#ccc}

/* contact */
.contact{display:grid;grid-template-columns:90px 1fr 42%;background:#f8f6f2}
.c-side{background:url('<?= img('contactside') ?>') center/cover}
.c-form{padding:60px 4%}
.c-form h2{margin-bottom:10px}
.c-form form{margin-top:24px}
.c-info{background:#f3efe9;padding:20px}
.map{border-radius:6px;overflow:hidden;height:280px;border:6px solid #fff;box-shadow:var(--sh)}
.map iframe{width:100%;height:100%;border:0}
.c-list{list-style:none;padding:26px 14px 10px;position:relative}
.c-list li{display:flex;gap:18px;margin-bottom:22px;font-size:13.5px}
.c-list li>svg{width:44px;height:44px;padding:11px;border-radius:50%;background:#ebe2d6;color:var(--gold)}
.c-list b{font-family:var(--serif);color:var(--ink);font-size:15.5px;display:block}
.c-list .script{position:absolute;right:10px;top:190px;font-size:38px}
.follow{padding:14px;border-top:1px solid #ddd;margin:0 14px}
.follow b{font-family:var(--serif);color:var(--ink)}
.follow nav{display:flex;gap:10px;margin-top:10px}
.follow a{width:36px;height:36px;border-radius:50%;display:grid;place-items:center;color:#fff}
.follow a:nth-child(1){background:#1877f2}.follow a:nth-child(2){background:radial-gradient(circle at 30% 110%,#fdc468,#df4996 50%,#7a3ce0)}.follow a:nth-child(3){background:#f00}.follow a:nth-child(4){background:#0a66c2}.follow a:nth-child(5){background:#e60023}
.c-perks{display:flex;margin-top:30px}
.c-perks div{flex:1;display:flex;align-items:center;justify-content:center;gap:12px;font-size:13.5px;color:var(--ink);border-right:1px solid #ddd}
.c-perks div:last-child{border:0}.c-perks svg{color:var(--gold)}
.alert{padding:14px 18px;border-radius:6px;margin:14px 0;font-size:14px;display:flex;gap:10px;align-items:center}
.alert.ok{background:#e7f5ea;color:#1d6b33;border:1px solid #bfe3c8}
.alert.err{background:#fdecea;color:#9b2c21;border:1px solid #f4c1bb}

/* footer */
.ftr{background:#16181d radial-gradient(circle at 0 40%,#1f2228,transparent 40%);color:#d0d0d0;padding-top:60px;position:relative;overflow:hidden}
.ftr-grid{display:grid;grid-template-columns:1.4fr .8fr .95fr 1.05fr 1.2fr;gap:34px;padding-bottom:40px}
.f-brand{display:flex;align-items:center;gap:12px}
.f-brand img{height:74px;background:#fff;border-radius:8px;padding:5px}
.f-brand b{white-space:nowrap;font-family:var(--sans);font-size:21px;color:#fff;letter-spacing:1px;display:block}
.f-brand b em{font-style:normal;color:var(--gold2)}
.f-brand small{font-size:10px;letter-spacing:1px;color:#ddd}
.f-about h3{color:#fff;font-size:30px;margin-top:26px;font-weight:600}
.gl{display:block;width:100px;height:2px;background:var(--gold);margin:14px 0 20px}
.f-about p{font-size:15px;line-height:1.75}
.f-soc{display:flex;gap:14px;margin:26px 0;padding-bottom:28px;border-bottom:1px solid #3a3d44}
.f-soc a{width:46px;height:46px;border-radius:50%;border:1px solid #ccc;display:grid;place-items:center;color:#fff;transition:.2s}
.f-soc a:hover{background:var(--gold);border-color:var(--gold)}
.f-vals{display:flex;justify-content:space-between;text-align:center;font-size:14.5px;color:#eee}
.f-vals svg{display:block;color:var(--gold2);margin:0 auto 8px;stroke-width:1.2}
.ftr h4{color:#fff;font-size:24px;font-weight:600;margin-bottom:34px;position:relative}
.ftr h4::after{content:'';position:absolute;left:0;bottom:-14px;width:68px;height:2px;background:var(--gold)}
.f-list{list-style:none}
.f-list>li{margin-bottom:22px}
.f-list a{display:flex;justify-content:space-between;align-items:center;font-size:15.5px;transition:.2s;gap:10px}
.f-list a:hover{color:var(--gold2);padding-left:4px}
.f-tree>li{border-bottom:1px solid #3a3d44;padding-bottom:12px;margin-bottom:14px}
.f-tree>li:last-child{border:0}
.f-tree ul{list-style:none;padding-left:20px;margin-top:6px}
.f-tree ul a{font-size:14.5px;padding:3px 0;color:#e8e8e8}
.f-contact{list-style:none}
.f-contact li{display:flex;gap:20px;margin-bottom:26px;font-size:15.5px;line-height:1.7}
.f-contact svg{color:var(--gold2);margin-top:2px}
.f-contact a:hover{color:var(--gold2)}
.f-acc{border-top:1px solid #3a3d44;padding-top:30px;font-size:22px!important}
.pay{display:flex;gap:8px;flex-wrap:wrap}
.pay span{height:36px;border-radius:4px;background:#fff;display:flex;align-items:center;justify-content:center;padding:0 10px;font-weight:800;font-size:15px}
.pay .visa{background:#1a3aa0;color:#fff;font-style:italic;font-size:17px}
.pay .mc i{width:22px;height:22px;border-radius:50%;background:#eb001b;display:block}
.pay .mc i+i{background:#f79e1b;margin-left:-9px;opacity:.9}
.pay .mc{background:transparent;padding:0 4px}
.pay .upi{color:#555;font-style:italic}.pay .upi b{color:#f47a20}
.pay .paytm{color:#0b2e6f}.pay .paytm b{color:#00baf2}
.pay .nb{color:#1c2b5a;font-size:10px;line-height:1.1;gap:6px;text-align:left}
.ftr-bot{display:flex;align-items:center;gap:40px;border-top:1px solid #3a3d44;padding:36px 0 50px;font-size:15px;flex-wrap:wrap;position:relative;z-index:1}
.ftr-bot nav{display:flex}
.ftr-bot nav a{padding:0 22px;border-left:1px solid #777;font-size:14.5px}
.ftr-bot nav a:first-child{border:0;padding-left:0}
.ftr-bot nav a:hover{color:var(--gold2)}
.f-script{margin-left:auto;font-family:var(--script);font-size:38px;color:#fff;transform:rotate(-12deg);border-bottom:2px solid var(--gold);line-height:1}
.f-sketch{position:absolute;right:30px;bottom:20px;width:340px;pointer-events:none}

/* page hero + misc pages */
.phero{position:relative;background:linear-gradient(90deg,rgba(250,248,244,.97) 30%,rgba(250,248,244,.55) 48%,rgba(250,248,244,0) 62%),var(--bg) right center/cover;padding:70px 0 60px}
.phero .wrap{display:flex;justify-content:space-between;align-items:center}
.phero-in{max-width:520px}
.phero h1{font-size:clamp(34px,4vw,50px);margin-bottom:12px}
.phero p{font-size:15.5px;color:var(--ink)}
.phero .script{margin-top:20px;font-size:34px}
.phero-side{color:#fff;letter-spacing:2px;font-size:13px;line-height:2;text-shadow:0 1px 6px rgba(0,0,0,.6);align-self:flex-start}
.phero-side i{display:block;width:40px;height:2px;background:var(--gold);margin-top:8px}
.crumbs{display:flex;align-items:center;gap:8px;font-size:13px;padding:16px 0;color:var(--mut)}
.crumbs a:hover{color:var(--gold)}.crumbs span{color:var(--ink)}
.two{display:grid;grid-template-columns:1fr 1fr;gap:50px;align-items:center}
.two img{border-radius:var(--r);box-shadow:var(--sh);width:100%}
.prose h2{font-size:30px;margin:30px 0 12px}.prose h3{font-size:22px;margin:24px 0 10px}
.prose p,.prose li{margin-bottom:12px;font-size:15.5px}
.prose ul{padding-left:22px}
.values{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-top:40px}
.values .card{padding:28px 22px;text-align:center}
.values svg{color:var(--gold);margin:0 auto 12px}
.values h3{font-size:18px;margin-bottom:6px}.values p{font-size:13.5px}
.tl{border-left:2px solid var(--goldl);padding-left:26px;margin-top:20px}
.tl div{position:relative;margin-bottom:24px}
.tl div::before{content:'';position:absolute;left:-33px;top:4px;width:12px;height:12px;border-radius:50%;background:var(--gold)}
.tl b{font-family:var(--serif);color:var(--ink);font-size:18px}
.blog-layout{display:grid;grid-template-columns:1fr 290px;gap:26px;align-items:start}
.filters{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;margin-bottom:26px;align-items:center}
.filters .tabs{margin:0}
.filters .tab{padding:7px 20px;font-size:13px}
.filters .tab.on{background:var(--ink);border-color:var(--ink)}
.search{display:flex;border:1px solid #ddd;border-radius:4px;background:#fff;align-items:center;padding-right:10px}
.search input{border:0;outline:0;padding:9px 12px;font-size:13px;background:transparent;width:180px}
.featured{display:grid;grid-template-columns:1.1fr 1fr;margin-bottom:18px}
.featured .zoom{min-height:300px}.featured .zoom img{width:100%;height:100%;object-fit:cover}
.featured>div:last-child{padding:26px 30px;display:flex;flex-direction:column;justify-content:center;align-items:flex-start}
.featured .pill{background:#f3e7d6;color:var(--ink);font-size:10.5px;letter-spacing:1.3px;padding:4px 10px;border-radius:3px;font-weight:600}
.featured h2{font-size:30px;margin:14px 0}
.featured .meta{color:var(--mut);margin:16px 0 20px}
.blog-grid.four{grid-template-columns:repeat(3,1fr)}
.side .card{padding:18px;margin-bottom:18px;background:#f4f2ef;box-shadow:none}
.side h4{font-size:17px;margin-bottom:12px}
.side .search{width:100%}.side .search input{flex:1}
.pp{display:flex;gap:12px;margin-bottom:12px;align-items:center}
.pp img{width:70px;height:50px;object-fit:cover;border-radius:3px}
.pp b{font-size:12.5px;color:var(--ink);font-weight:500;display:block;line-height:1.3}
.pp small{font-size:11px}
.cats{list-style:none;font-size:13px}
.cats li{display:flex;justify-content:space-between;padding:4px 0}
.cats li a:hover{color:var(--gold)}
.pager{display:flex;justify-content:center;gap:16px;align-items:center;margin-top:30px;font-size:13px}
.pager b{width:30px;height:30px;border-radius:50%;background:var(--ink);color:#fff;display:grid;place-items:center;font-weight:500}
.post-hero{height:420px;border-radius:var(--r);overflow:hidden;margin-bottom:30px}
.post-hero img{width:100%;height:100%;object-fit:cover}
.jobs{display:grid;gap:14px}
.job{display:flex;align-items:center;justify-content:space-between;padding:22px 26px;gap:20px;flex-wrap:wrap}
.job h3{font-size:20px}.job .meta{color:var(--mut);margin-top:6px}
.smap{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.smap .card{padding:26px}.smap a{display:block;padding:6px 0;color:var(--txt)}.smap a:hover{color:var(--gold)}
.nf{text-align:center;padding:120px 0}.nf b{font-family:var(--serif);font-size:120px;color:var(--gold);display:block;line-height:1}

.wa-float{position:fixed;right:22px;bottom:22px;width:56px;height:56px;border-radius:50%;background:#25d366;color:#fff;display:grid;place-items:center;box-shadow:0 8px 24px rgba(0,0,0,.25);z-index:60;animation:pulse 2.4s infinite}
@keyframes pulse{0%,100%{box-shadow:0 0 0 0 rgba(37,211,102,.5)}50%{box-shadow:0 0 0 14px rgba(37,211,102,0)}}
.totop{position:fixed;right:30px;bottom:92px;width:40px;height:40px;border-radius:50%;border:0;background:var(--ink);color:#fff;display:grid;place-items:center;z-index:60;cursor:pointer;opacity:0;visibility:hidden;transition:.3s;transform:rotate(180deg)}
.totop.show{opacity:1;visibility:visible}
.lightbox{position:fixed;inset:0;background:rgba(0,0,0,.92);z-index:100;display:none;align-items:center;justify-content:center;flex-direction:column;padding:30px}
.lightbox.show{display:flex}
.lightbox img{max-height:80vh;max-width:90vw;border-radius:6px}
.lightbox p{color:#fff;margin-top:14px;font-family:var(--serif);font-size:20px}
.lightbox button{position:absolute;top:20px;right:24px;background:none;border:0;color:#fff;cursor:pointer}

/* responsive */
@media (min-width:1181px){.featstrip{flex-wrap:nowrap!important}}
@media (max-width:1380px){.hdr-ph{display:none!important}.nav{gap:26px}}
@media (max-width:1180px){
  .nav{gap:18px}.brand small{display:none}
  .ftr-grid{grid-template-columns:1fr 1fr 1fr}.f-about{grid-column:1/-1}
