/* =================== JAVASCRIPT =================== */
function site_js() { ?>
(function(){
const $=(s,c=document)=>c.querySelector(s),$$=(s,c=document)=>[...c.querySelectorAll(s)];
// sticky header + back to top
const hdr=$('#hdr'),tt=$('#totop');
addEventListener('scroll',()=>{hdr.classList.toggle('sticky',scrollY>40);tt.classList.toggle('show',scrollY>600)},{passive:true});
tt.onclick=()=>scrollTo({top:0});
// mobile menu
const nav=$('#nav');$('#burger').onclick=e=>{e.stopPropagation();nav.classList.toggle('open')};
document.addEventListener('click',e=>{if(!nav.contains(e.target))nav.classList.remove('open')});
// reveal
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}}),{threshold:.12});
$$('.reveal').forEach(el=>io.observe(el));
// counters
const co=new IntersectionObserver(es=>es.forEach(e=>{if(!e.isIntersecting)return;const el=e.target,n=+el.dataset.count;let i=0;const t=setInterval(()=>{i+=Math.ceil(n/40);if(i>=n){i=n;clearInterval(t)}el.textContent=i+'+'},30);co.unobserve(el)}),{threshold:.6});
$$('[data-count]').forEach(el=>co.observe(el));
// simple tabs
$$('[data-tabs]').forEach(g=>g.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;$$('button',g).forEach(x=>x.classList.remove('on'));b.classList.add('on')}));
// filter tabs
$$('[data-filter]').forEach(g=>g.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;$$('button',g).forEach(x=>x.classList.remove('on'));b.classList.add('on');const f=b.dataset.f,box=g.closest('.wrap');$$('[data-cat]',box).forEach(c=>{c.style.display=(f==='All'||c.dataset.cat.indexOf(f.replace(' Design',''))>-1)?'':'none'})}));
// blog search
const bs=$('[data-search]');if(bs)bs.oninput=()=>{const q=bs.value.toLowerCase();$$('#bl_list>[data-t]').forEach(c=>c.style.display=c.dataset.t.includes(q)?'':'none')};
// sliders
$$('.circ[data-dir],.circ[data-slide]').forEach(b=>b.addEventListener('click',()=>{const sec=b.closest('section')||document;const s=$('[data-slider]',sec);if(!s)return;const d=+(b.dataset.dir||b.dataset.slide);const card=s.firstElementChild;s.scrollBy({left:d*(card.offsetWidth+24),behavior:'smooth'})}));
$$('[data-slider]').forEach(s=>{let t=setInterval(()=>{if(s.scrollLeft+s.clientWidth>=s.scrollWidth-5)s.scrollTo({left:0});else s.scrollBy({left:s.firstElementChild.offsetWidth+24})},4500);s.addEventListener('pointerenter',()=>clearInterval(t))});
// accordion
$$('.qa').forEach(q=>{const a=$('.ans',q);if(q.classList.contains('open'))a.style.maxHeight=a.scrollHeight+'px';$('button',q).onclick=()=>{const open=q.classList.contains('open');$$('.qa').forEach(x=>{x.classList.remove('open');$('.ans',x).style.maxHeight=0});if(!open){q.classList.add('open');a.style.maxHeight=a.scrollHeight+'px'}}});
// lightbox
const lb=$('#lightbox');
document.addEventListener('click',e=>{const t=e.target.closest('[data-lb]');if(!t)return;$('img',lb).src=t.dataset.lb;$('p',lb).textContent=t.dataset.cap||'';lb.classList.add('show')});
lb.onclick=e=>{if(e.target.tagName!=='IMG')lb.classList.remove('show')};
addEventListener('keydown',e=>{if(e.key==='Escape')lb.classList.remove('show')});
// visualizer
const vi=$('#viz_img');
if(vi){const th=$$('.theme');th.forEach(b=>b.onclick=()=>{th.forEach(x=>x.classList.remove('on'));b.classList.add('on');vi.style.filter=b.dataset.filter;$('#viz_name').textContent=b.dataset.name;$('#viz_desc').textContent=b.dataset.desc});$('#viz_reset').onclick=()=>th[0].click()}
// floor planner
const pf=$('#pform');
if(pf){
  const v=id=>$('#'+id).value,sum=k=>$('[data-k="'+k+'"]');
  const upd=()=>{const w=+v('p_w')||0,d=+v('p_d')||0,fl=+v('p_floors'),area=w*d;
    sum('type').textContent=v('p_type');sum('floors').textContent=fl;
    sum('plot').textContent=w+' ft x '+d+' ft ('+area.toLocaleString('en-IN')+' sq.ft.)';
    sum('bed').textContent=v('p_bed');sum('bath').textContent=v('p_bath');sum('style').textContent=v('p_style');
    const sp=$$('#p_spaces input:checked').map(i=>i.value.replace(' Room','').replace(' Area',''));
    sum('spaces').textContent=sp.join(', ')||'—';
    sum('built').textContent='~ '+(Math.round(area*.8*fl/100)*100).toLocaleString('en-IN')+' sq.ft.';
    $('#plan_field').value=[v('p_type'),fl+' floors',w+'x'+d+' ft',v('p_bed')+' bed',v('p_bath')+' bath',v('p_style'),v('p_budget'),sp.join('/')].join(' | ');
  };
  pf.addEventListener('input',upd);pf.addEventListener('change',upd);upd();
  $('#genplan').onclick=()=>{upd();const img=$('#pv_img');img.style.opacity=.2;setTimeout(()=>img.style.opacity=1,400);$('#getplan').style.display='block';$('#getplan').scrollIntoView({behavior:'smooth',block:'center'})};
  $$('[data-pv] button').forEach(b=>b.addEventListener('click',()=>{$$('[data-pv] button').forEach(x=>x.classList.remove('on'));b.classList.add('on');const i=$('#pv_img');i.src=b.dataset.img;i.style.transform=b.dataset.flip?'scaleX(-1)':''}));
}
// state -> city
const cities={'Madhya Pradesh':['Gwalior','Indore','Bhopal','Jabalpur','Ujjain','Sagar','Dewas','Satna','Rewa','Morena','Shivpuri','Datia','Bhind','Other'],'Rajasthan':['Jaipur','Jodhpur','Udaipur','Kota','Other'],'Uttar Pradesh':['Lucknow','Agra','Jhansi','Kanpur','Noida','Other'],'Maharashtra':['Mumbai','Pune','Nagpur','Nashik','Other'],'Chhattisgarh':['Raipur','Bilaspur','Durg','Other'],'Gujarat':['Ahmedabad','Surat','Vadodara','Other'],'Delhi':['New Delhi','Other'],'Other':['Other']};
const st=$('#c_state'),ct=$('#c_city');
if(st)st.onchange=()=>{ct.innerHTML='<option value="">Select City</option>'+(cities[st.value]||[]).map(c=>'<option>'+c+'</option>').join('')};
})();
<?php }

