  case 'post': page_post(); break;
  case 'careers': page_careers(); break;
  case 'contact':
    echo page_hero('Get in Touch', 'Contact Us', "Let's talk about your dream project. Visit, call or send us a message.", 'villa', "Let's<br>&nbsp;Stay Connected");
    sec_contact('contact'); sec_faq(); break;
  case 'privacy': case 'terms': case 'refund': page_policy($page); break;
  case 'sitemap': page_sitemap(); break;
  default:
    echo '<div class="nf wrap"><b>404</b><h2>Page not found</h2><p class="lead" style="margin:14px auto 26px">The page you are looking for does not exist.</p><a class="btn" href="' . url('home') . '">Back to Home ' . ic('arrow', 16) . '</a></div>';
}
site_footer();
